{"implementation": "def solve(case):
    import sys
    payload = case.get('payload', case)
    passing = payload.get('passing')
    failing = payload.get('failing')
    required_diff = payload.get('required_difference', [])
    unresolved_diff = payload.get('unresolved_difference', [])
    if not isinstance(passing, list) or not isinstance(failing, list) or not isinstance(required_diff, list) or not isinstance(unresolved_diff, list):
        raise ValueError('Invalid fields')
    passing_set = set(passing)
    # ordered difference (elements in failing but not in passing, preserving failing order)
    D = [x for x in failing if x not in passing_set]
    req_set = set(required_diff)
    unres_set = set(unresolved_diff)
    if not req_set.issubset(set(D)):
        # required must be subset of difference, else no solution? treat as empty
        return {'difference': [], 'tests': 0}
    if not unres_set.issubset(set(D)):
        raise ValueError('unresolved must be subset of difference')
    test_count = 0
    def test(sub):
        nonlocal test_count
        test_count += 1
        if not sub:
            return 'PASS'
        if not req_set.issubset(set(sub)):
            return 'PASS'
        if set(sub).intersection(unres_set):
            return 'UNRESOLVED'
        return 'FAIL'
    def split(lst, n):
        # split lst into n roughly equal parts preserving order
        size = len(lst)
        q, r = divmod(size, n)
        parts = []
        start = 0
        for i in range(n):
            end = start + q + (1 if i < r else 0)
            parts.append(lst[start:end])
            start = end
        return parts
    def ddmin(cs):
        # cs is list of elements
        if len(cs) == 1:
            return cs
        n = 2
        while n <= len(cs):
            subsets = split(cs, n)
            # test each subset
            for subset in subsets:
                if not subset:
                    continue
                res = test(subset)
                if res == 'FAIL':
                    return ddmin(subset)
            # test complements
            complements = []
            for i in range(len(subsets)):
                comp = []
                for j, part in enumerate(subsets):
                    if j != i:
                        comp.extend(part)
                complements.append(comp)
            for comp in complements:
                if not comp:
                    continue
                res = test(comp)
                if res == 'FAIL':
                    return ddmin(comp)
            n *= 2
        return cs
    result = ddmin(D)
    return {'difference': result, 'tests': test_count}
